#!/usr/bin/env python3
import base64, gzip, subprocess, sys

PATCH_B64 = ""
patch = gzip.decompress(base64.b64decode(PATCH_B64))
proc = subprocess.run(["git", "apply", "--whitespace=nowarn", "-"], input=patch)
if proc.returncode != 0:
    sys.exit(proc.returncode)
print("Applied LineAssistant 1.4.9 OCR/layout fix")
